import pandas as pd, numpy as np
from scipy import stats
for eid in [1,2,3,6,8,9]:
    try:
        df=pd.read_csv(eval(f"experiment_{eid}_csv"))
        print("=== exp",eid,"cols:",list(df.columns))
        if "CapacityRetention" in df.columns:
            for c in df.columns:
                if c!="CapacityRetention" and df[c].dtype!=object:
                    try:
                        r,p=stats.pearsonr(df[c],df["CapacityRetention"])
                        print(f"  {c}: r={r:.2f} p={p:.1e} mean={df[c].mean():.2f}")
                    except: pass
    except Exception as e:
        print(eid,"err",e)
